/**
 * VendCota Design System — tokens
 * Fonte da verdade visual. Não redefina cores fora daqui.
 * Importe este arquivo uma vez, no root do app (ex.: app/globals.css @import).
 */
:root{
  --bg:#F5F5F3; --surface:#FFFFFF; --surface2:#FAFAF8; --side:#F5F5F3;
  --line:#E6E6E2; --line2:#D9D9D4;
  --tx:#171716; --tx2:#5C5C57; --tx3:#8F8F89; --tx4:#B5B5AF;

  --accent:#2F55D4; --accent-soft:#E9EEFB; --accent-line:#2F55D4;
  --ok:#1F7A4C; --ok-soft:#E6F3EB;
  --warn:#A6660A; --warn-soft:#FAF1DF;

  --grid:#EFEFEC; --spark:#CFCFCA; --ghost:#C3C3BE;
  --shadow:0 1px 2px rgba(0,0,0,.03);
  --r:6px;         /* raio padrão — cards, botões, inputs, tags */
  --r-full:9999px; /* pills / avatares */

  --font-sans:"Geist","Inter",system-ui,-apple-system,sans-serif;
  --font-mono:"Geist Mono",ui-monospace,"SF Mono","JetBrains Mono",Menlo,Consolas,monospace;
}

[data-theme="dark"]{
  --bg:#0E0E0D; --surface:#151514; --surface2:#1A1A19; --side:#0E0E0D;
  --line:#242423; --line2:#2E2E2C;
  --tx:#EDEDEA; --tx2:#A5A5A0; --tx3:#75756F; --tx4:#4E4E4A;

  --accent:#8FA5F5; --accent-soft:#1B2340; --accent-line:#7B93F0;
  --ok:#5FC48E; --ok-soft:#14261C;
  --warn:#E0A84A; --warn-soft:#2B2213;

  --grid:#1F1F1E; --spark:#3A3A38; --ghost:#3A3A38;
  --shadow:none;
}

/*
 * Regras de uso (leia antes de criar um componente novo):
 * 1. Cor de acento é ÚNICA (--accent). Nunca introduza uma segunda cor "de marca".
 *    Semânticas extras são só --ok (sucesso/reunião) e --warn (atenção/escalada).
 * 2. Números e dados tabulares (horários, %, R$, contadores) sempre em --font-mono.
 *    Texto corrido, rótulos e frases sempre em --font-sans.
 * 3. Um raio só: var(--r) = 6px, em tudo (card, botão, input, tag, avatar quadrado).
 *    Avatares circulares e badges numéricos usam var(--r-full).
 * 4. Hairlines (var(--line)) fazem a separação visual — não use sombra para dividir
 *    seções. --shadow só existe para dar um leve "levante" a cards no modo claro
 *    (é vazio no dark).
 * 5. Nunca hardcode um hex fora deste arquivo. Se faltar um token, adicione aqui
 *    (nos dois temas) antes de usar em um componente.
 */

/**
 * Extensão de tema do Tailwind para o VendCota Design System.
 * Faça merge disto no tailwind.config.js do projeto (ou `require` e espalhe
 * dentro de theme.extend). Os valores são todos `var(--...)`, então dark mode
 * funciona só trocando `data-theme` no <html> — nenhuma classe `dark:` é necessária
 * nos componentes.
 */
module.exports = {
  darkMode: ['selector', '[data-theme="dark"]'],
  theme: {
    extend: {
      colors: {
        bg: 'var(--bg)',
        surface: 'var(--surface)',
        surface2: 'var(--surface2)',
        side: 'var(--side)',
        line: 'var(--line)',
        line2: 'var(--line2)',
        tx: 'var(--tx)',
        tx2: 'var(--tx2)',
        tx3: 'var(--tx3)',
        tx4: 'var(--tx4)',
        accent: 'var(--accent)',
        'accent-soft': 'var(--accent-soft)',
        'accent-line': 'var(--accent-line)',
        ok: 'var(--ok)',
        'ok-soft': 'var(--ok-soft)',
        warn: 'var(--warn)',
        'warn-soft': 'var(--warn-soft)',
        grid: 'var(--grid)',
        spark: 'var(--spark)',
        ghost: 'var(--ghost)',
      },
      borderRadius: {
        ds: 'var(--r)',
        'ds-full': 'var(--r-full)',
      },
      boxShadow: {
        ds: 'var(--shadow)',
      },
      fontFamily: {
        sans: ['var(--font-sans)'],
        mono: ['var(--font-mono)'],
      },
      fontSize: {
        // escala usada nas telas — não invente tamanhos fora daqui
        xs: ['11.5px', '1.4'],
        sm: ['12.5px', '1.45'],
        base: ['13.5px', '1.5'],
        md: ['14.5px', '1.4'],
        lg: ['17px', '1.3'],
        xl: ['22px', '1.15'],
        '2xl': ['28px', '1.1'],
        '3xl': ['44px', '1'],
      },
    },
  },
};
